{
  "type": "object",
  "description": "Schema for capturing updated qualification details of an employee. Fields are populated based on user input and reference data from the 'qualificationTypesandQualification' tool. This schema is used in the final save API. if the user update qualification type then ask follow qualification.",
  "properties": {
    "employeeNumber": {
      "type": "string",
      "description": "Unique identifier for the employee."
    },
    "qualificationTypeId": {
      "type": "string",
      "description": "ID for the selected qualification type. Fetched from a displayed list based on the 'qualificationTypesandQualification' tool."
    },
    "qualificationId": {
      "type": "string",
      "description": "ID for the selected qualification. Derived from user selection after loading data using the 'qualificationTypesandQualification' API."
    },
    "qualificationEffectStartDate": {
      "type": "string",
      "format": "date",
      "description": "'qualificationEffectStartDate' The qualification effect start date must strictly follow the 'm/d/YYYY' format and should be captured before calling the final API. the 'qualificationEffectStartDate' should be used. Additionally, the AI must not generate any random dates during this process."
    },
    "qualificationEffectEndDate": {
      "type": "string",
      "format": "date",
      "description": "'qualificationEffectEndDate' The qualification effect end date must strictly follow the 'm/d/YYYY' format and should be captured before calling the final API. the 'qualificationEffectEndDate' should be used. Additionally, the AI must not generate any random dates during this process."
    },
    "institutionName": {
      "type": "string",
      "description": "Name of the school or institute where the qualification was obtained."
    },
    "highestQualification": {
      "type": "string",
      "enum": [
        "on",
        "off"
      ],
      "description": "in this highest Qualification to before api for 'qualificationTypesandQualification' api."
    },
    "qualificationStatus": {
      "type": "string",
      "enum": [
        "0",
        "1",
        "2",
        "3",
        "4",
        "5"
      ],
      "description": "Status of the qualification (e.g., 0: Pass, 1: First Class, 2: Second Class, etc.)."
    },
    "jobRelated": {
      "type": "string",
      "enum": [
        "0",
        "1"
      ],
      "description": "Indicates whether the qualification is job-related (0 = No, 1 = Yes).to get before api respsone."
    },
    "durationValue": {
      "type": "string",
      "description": "Numeric duration of the qualification if the user given duration number must should following example format for example 5 you will be take for 5.00.(e.g., 3.00)."
    },
    "durationType": {
      "type": "string",
      "enum": [
        "000001",
        "000002",
        "000003",
        "000004",
        "000005"
      ],
      "description": "Type of duration (Years, Months, Weeks, Days, Hours)."
    },
    "yearOfPassing": {
      "type": "string",
      "description": "Year in which the qualification was completed (e.g., 2023). in this year of passing to get for 'qualificationTypesandQualification' api."
    },
    "comments": {
      "type": "string",
      "description": "Additional comments about the qualification, if any."
    },
    "totalCost": {
      "type": "string",
      "description": "Total cost associated with obtaining the qualification. Retrieved from the 'qualificationTypesandQualification' API."
    },
    "currencyForTotalCost": {
      "type": "string",
      "description": "Currency code for the total cost. Selected from a list of currencies retrieved using the 'qualificationTypesandQualification' API."
    },
    "CostEffectDate": {
      "type": "string",
      "format": "date",
      "description": "'totalCostEffectiveDate' Effective date of the total cost in m/d/YYYY must should followin in this date m/d/YYYY format."
    },
    "reimbursedAmount": {
      "type": "string",
      "description": "Amount reimbursed by the company. Retrieved from the 'qualificationTypesandQualification' API."
    },
    "currencyForReimbursement": {
      "type": "string",
      "description": "Currency code for the reimbursed amount. Selected from a list of currencies using the 'qualificationTypesandQualification' API."
    },
    "reimbursementEffectDate": {
      "type": "string",
      "format": "date",
      "description": "'reimbursedEffectiveDate' Effective date of the reimbursement in m/d/YYYY must should followin in this date m/d/YYYY format."
    }
  },
  "required": [
    "employeeNumber",
    "qualificationTypeId",
    "qualificationId",
    "institutionName",
    "qualificationStatus",
    "durationValue",
    "durationType",
    "CostEffectDate",
    "reimbursementEffectDate",
    "highestQualification",
    "jobRelated",
    "qualificationEffectStartDate",
    "qualificationEffectEndDate"
  ]
}

